34. // Memory Region Type
35. //==================================================================================================
36. 
37. ///
38. /// # Description
39. ///
40. /// A type that represents the type of a memory region.
41. ///
42. #[derive(Debug, Clone, Copy, Eq, PartialEq)]
43. #[verus_verify]
44. pub enum MemoryRegionType {
45.     /// Usable memory.
46.     Usable,
47.     /// Reserved memory.
48.     Reserved,
49.     /// Memory mapped I/O.
50.     Mmio,
51.     /// Bad memory.
52.     Bad,
53. }
