295. //==================================================================================================
296. // Truncated Memory Region
297. //==================================================================================================
298. 
299. ///
300. /// # Description
301. ///
302. /// A memory region that has been truncated to a multiple of a page size.
303. ///
304. #[verus_verify(external_derive)]
305. #[derive(Clone)]
306. pub struct TruncatedMemoryRegion<T: Address>(MemoryRegion<PageAligned<T>>);
307. 
308. impl<T: Address> TruncatedMemoryRegion<T> {
309.     /// Creates a new truncated memory region.
310.     pub fn new(
311.         name: &str,
312.         start: PageAligned<T>,
313.         size: usize,
314.         typ: MemoryRegionType,
315.         perm: AccessPermission,
316.     ) -> Result<Self, Error> {
317.         // Truncate the size of the memory region to a multiple of the page size.
318.         let size: usize = ::sys::mm::align_up(size, PAGE_ALIGNMENT).ok_or_else(|| {
319.             let reason: &str = "align_up overflow";
320.             error!("TruncatedMemoryRegion::new(): {reason} (name={name:?}, size={size})");
321.             Error::new(ErrorCode::InvalidArgument, reason)
322.         })?;
323.         Ok(Self(MemoryRegion::new(name, start, size, typ, perm)?))
324.     }
325. 
326.     ///
327.     /// # Description
328.     ///
329.     /// Creates a new truncated MMIO memory region with an explicit cache policy.
330.     ///
331.     /// # Parameters
332.     ///
333.     /// - `name`: Name of the memory region.
334.     /// - `start`: Page-aligned start address.
335.     /// - `size`: Size of the region in bytes (rounded up to page alignment).
336.     /// - `perm`: Access permissions for the region.
337.     /// - `cache_policy`: Caching policy that controls PWT/PCD bits in page table entries.
338.     ///
339.     /// # Returns
340.     ///
341.     /// Upon successful completion, a new [`TruncatedMemoryRegion`] with type
342.     /// [`MemoryRegionType::Mmio`] is returned. Upon failure, an error is returned instead.
343.     ///
344.     pub fn new_mmio(
345.         name: &str,
346.         start: PageAligned<T>,
347.         size: usize,
348.         perm: AccessPermission,
349.         cache_policy: MmioCachePolicy,
350.     ) -> Result<Self, Error> {
351.         let mut region: Self = Self::new(name, start, size, MemoryRegionType::Mmio, perm)?;
352.         region.0.set_cache_policy(cache_policy);
353.         Ok(region)
354.     }
355. 
356.     pub fn from_memory_region(region: MemoryRegion<T>) -> Result<Self, Error> {
357.         let cache_policy: Option<MmioCachePolicy> = region.cache_policy();
358.         let start: T = region.start().align_down(PAGE_ALIGNMENT)?;
359.         let start: PageAligned<T> = PageAligned::from_address(start)?;
360.         let name: String = region.name();
361.         let size: usize = region.size();
362.         let typ: MemoryRegionType = region.typ();
363.         let perm: AccessPermission = region.perm();
364.         let mut truncated: Self = Self::new(&name, start, size, typ, perm)?;
365.         if let Some(policy) = cache_policy {
366.             truncated.0.set_cache_policy(policy);
367.         }
368.         Ok(truncated)
369.     }
370. 
371.     pub fn name(&self) -> String {
372.         self.0.name()
373.     }
374. 
375.     /// Returns the first valid address that lies in the target memory region.
376.     #[verus_spec(result =>
377.         ensures
378.             // Faithful read, delegated to the inner region. The returned
379.             // `PageAligned<T>` carries the same abstract address as the stored
380.             // start (`spec_addr(&result) == self@.start`); page alignment of that
381.             // address follows from `self.inv()`.
382.             crate::hal::mem::spec_addr(&result) == self@.start,
383.     )]
384.     pub fn start(&self) -> PageAligned<T> {
385.         self.0.start()
386.     }
387. 
388.     /// Returns the size of the target memory region.
389.     #[verus_spec(result =>
390.         ensures
391.             result as int == self@.size,
392.     )]
393.     pub fn size(&self) -> usize {
394.         self.0.size()
395.     }
396. 
397.     /// Returns the type of the target memory region.
398.     pub fn typ(&self) -> MemoryRegionType {
399.         self.0.typ()
400.     }
401. 
402.     /// Returns the permissions of the target memory region.
403.     pub fn perm(&self) -> AccessPermission {
404.         self.0.perm()
405.     }
406. 
407.     ///
408.     /// # Description
409.     ///
410.     /// Returns the MMIO cache policy of the target memory region, if set.
411.     ///
412.     /// # Returns
413.     ///
414.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
415.     ///
416.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
417.         self.0.cache_policy()
418.     }
419. }
420. 
421. impl<T: Address> PartialEq for TruncatedMemoryRegion<T> {
422.     fn eq(&self, other: &Self) -> bool {
423.         self.0 == other.0
424.     }
425. }
426. 
427. impl<T: Address> Eq for TruncatedMemoryRegion<T> {}
428. 
429. impl<T: Address> PartialOrd for TruncatedMemoryRegion<T> {
430.     fn partial_cmp(&self, other: &Self) -> Option<core::cmp::Ordering> {
431.         Some(self.cmp(other))
432.     }
433. }
434. 
435. impl<T: Address> Ord for TruncatedMemoryRegion<T> {
436.     fn cmp(&self, other: &Self) -> core::cmp::Ordering {
437.         self.0.cmp(&other.0)
438.     }
439. }
440. 
441. impl<T: Address> core::fmt::Debug for TruncatedMemoryRegion<T> {
442.     fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
443.         write!(
444.             f,
445.             "TruncatedMemoryRegion {{ name: {}, start: {:?}, size: {}, typ: {:?}, perm: {:?}, \
446.              cache_policy: {:?} }}",
447.             self.name(),
448.             self.start(),
449.             self.size(),
450.             self.typ(),
451.             self.perm(),
452.             self.cache_policy()
453.         )
454.     }
455. }
