461. impl TruncatedMemoryRegion<PhysicalAddress> {
462.     /// Attempts to create a virtual memory region from a physical memory region.
463.     pub fn from_virtual_memory_region(region: MemoryRegion<VirtualAddress>) -> Result<Self, Error> {
464.         let name: String = region.name();
465.         let start: PageAligned<PhysicalAddress> =
466.             PageAligned::from_address(PhysicalAddress::from_virtual_address(region.start())?)?;
467.         let size: usize = region.size();
468.         let typ: MemoryRegionType = region.typ();
469.         let perm: AccessPermission = region.perm();
470.         TruncatedMemoryRegion::new(&name, start, size, typ, perm)
471.     }
472. }
